import React, { useState } from "react";
import AdminProductDetails from "../AdminProductDetails/AdminProductDetails";
import ProductList from "../ProductList/AdminProductList";
import AdminOrderList from "../Orders/AdminOrderList";
import OrderDetails from "../Orders/OrderDetails";
import { getBaseURL } from "../apiConfig";
import axios from "axios";
import "./AdminContainer.scss";

const AdminContainer = (props) => {
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [selectedOrder, setSelectedOrder] = useState(null);
  const [showProductList, setShowProductList] = useState(true);
  const [productName, setProductName] = useState("");
  const [productPrice, setProductPrice] = useState(0);
  const [productDesc, setProductDesc] = useState("");
  const [productStock, setProductStock] = useState(0); // État pour le stock

  const handleProductDetails = (product) => {
    if (props.isAdmin === 1) {
      setSelectedProduct(product);
    } else {
      alert("Access denied: Only admins can view product details.");
    }
  };

  const addProduct = () => {
    if (!productName || productPrice <= 0 || !productDesc || productStock < 0) {
      alert("Please fill in all fields correctly.");
      return;
    }

    const newProduct = {
      name: productName,
      price: productPrice,
      description: productDesc,
      stock: productStock,
    };

    axios
      .post(`${getBaseURL()}api/products/create`, newProduct)
      .then(() => {
        alert("Product added successfully!");
        setProductName("");
        setProductPrice(0);
        setProductDesc("");
        setProductStock(0);
      })
      .catch((err) => {
        console.error("Error adding product:", err);
        alert("Failed to add product. Please try again.");
      });
  };

  return (
    <div className="admin-container">
      {selectedProduct ? (
        <div className="details-container">
          <AdminProductDetails
            productId={selectedProduct.productId}
            onBackClick={() => setSelectedProduct(null)}
          />
        </div>
      ) : (
        <>
          <div>
            {showProductList ? (
              <div className="product-list-container">
                <div className="add-product-section">
                  <h2>Add a Product</h2>
                  <label>Product Name:</label>
                  <input
                    type="text"
                    value={productName}
                    onChange={(e) => setProductName(e.target.value)}
                  />
                  <label>Price:</label>
                  <input
                    type="number"
                    value={productPrice}
                    onChange={(e) => setProductPrice(parseFloat(e.target.value))}
                  />
                  <label>Description:</label>
                  <input
                    type="text"
                    value={productDesc}
                    onChange={(e) => setProductDesc(e.target.value)}
                  />
                  <label>Stock:</label>
                  <input
                    type="number"
                    value={productStock}
                    onChange={(e) => setProductStock(parseInt(e.target.value, 10))}
                  />
                  <button onClick={addProduct}>Add Product</button>
                </div>

                {props.isAdmin === 1 && (
                  <button onClick={() => setShowProductList(false)}>
                    Get Order List
                  </button>
                )}
                <ProductList
                  isAdmin={props.isAdmin}
                  handleProductDetails={handleProductDetails}
                />
              </div>
            ) : (
              <div className="order-list-container">
                {selectedOrder ? (
                  <div className="details-container">
                    <OrderDetails
                      orderId={selectedOrder.orderId}
                      onBackClick={() => setSelectedOrder(null)}
                    />
                  </div>
                ) : (
                  <div>
                    <button onClick={() => setShowProductList(true)}>
                      Get Product List
                    </button>
                    <AdminOrderList handleOrderDetails={setSelectedOrder} />
                  </div>
                )}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
};

export default AdminContainer;
